import { colors } from '@/theme'
import { defineStyles } from '@/utils'
import { ChevronRight } from 'lucide-react-native'
import { TouchableOpacity, Text } from 'react-native'
import { redirectAfterAuth } from '@/utils/redirect-after-auth'
import { prePromptStoreRating } from '@/utils/pre-prompt-store-rating'
import { useBoolVariation } from '@launchdarkly/react-native-client-sdk'

export const SkipButton = ({ show }: { show: boolean }) => {
	const promptRatingOnboardingEnabled = useBoolVariation(
		'prompt-rating-onboarding-enabled',
		false
	)

	const handleSkip = async () => {
		if (promptRatingOnboardingEnabled) {
			await prePromptStoreRating(true)
		}
		await redirectAfterAuth()
	}

	return (
		<TouchableOpacity
			disabled={!show}
			style={[styles.skipButton, { opacity: show ? 1 : 0 }]}
			onPress={handleSkip}
		>
			<Text style={styles.skipButtonText}>Skip</Text>
			<ChevronRight size={20} color={colors.light.white} />
		</TouchableOpacity>
	)
}

const styles = defineStyles({
	skipButton: {
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		gap: 4
	},
	skipButtonText: {
		color: colors.light.white,
		fontSize: 16,
		fontWeight: '500'
	}
})
